public class Nodo {

    private String codigo;
    private double capacidadMaxima;
    private boolean tieneGPU;
    private boolean ocupado;

    public Nodo(String codigo, double capacidadMaxima, boolean tieneGPU) {

        // Rechaza códigos nulos, vacíos o formados solo por espacios.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código del nodo no puede estar vacío."
            );
        }

        // La capacidad debe ser un número positivo y finito.
        if (!Double.isFinite(capacidadMaxima) || capacidadMaxima <= 0) {
            throw new IllegalArgumentException(
                "La capacidad máxima debe ser positiva y finita."
            );
        }

        this.codigo = codigo.trim();
        this.capacidadMaxima = capacidadMaxima;
        this.tieneGPU = tieneGPU;
        this.ocupado = false;
    }

    // Reserva el nodo para un lote nuevo.
    public void ocupar() {
        // Impide que el nodo tenga dos lotes sin cerrar.
        if (ocupado) {
            throw new IllegalStateException(
                "El nodo ya tiene un lote sin cerrar."
            );
        }

        // Marca el nodo como reservado.
        this.ocupado = true;
    }

    // Libera el nodo cuando su lote se cierra.
    public void liberar() {
        // Permite que el nodo reciba un nuevo lote.
        this.ocupado = false;
    }

    public String getCodigo() {
        return codigo;
    }

    public double getCapacidadMaxima() {
        return capacidadMaxima;
    }

    public boolean isTieneGPU() {
        return tieneGPU;
    }

    public boolean isOcupado() {
        return ocupado;
    }

    // Devuelve una descripción del nodo para las consultas.
    @Override
    public String toString() {
        // Presenta su código, capacidad, GPU y disponibilidad.
        return "Nodo: " + codigo
                + " | Capacidad máxima: " + capacidadMaxima + " horas"
                + " | GPU: " + (tieneGPU ? "Sí" : "No")
                + " | Estado: " + (ocupado ? "Ocupado" : "Libre");
    }
}